TP.register({id:"lp1-gtk",lp:1,grade:"TK",mode:"baseline",nextGrade:"Kindergarten",build(E){const F=E.F;const INK="#6B4A3C",PUPIL="#4A332A",BLUSH="#F49AAB";const kEye=(x,y,r)=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}" fill="${PUPIL}"/>`;const kBlush=(x,y,r)=>`<ellipse cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" rx="${(r*1.5).toFixed(1)}" ry="${(r*.95).toFixed(1)}" fill="${BLUSH}" opacity=".88"/>`;const kSmile=(x,y,w,sw)=>`<path d="M${(x-w).toFixed(1)} ${y.toFixed(1)} q${w.toFixed(1)} ${(w*1.05).toFixed(1)} ${(w*2).toFixed(1)} 0" fill="none" stroke="${PUPIL}" stroke-width="${sw.toFixed(1)}" stroke-linecap="round"/>`;const kFace=(cx,cy,r)=>kEye(cx-r*.38,cy-r*.06,r*.16)+kEye(cx+r*.38,cy-r*.06,r*.16)+kBlush(cx-r*.72,cy+r*.3,r*.17)+kBlush(cx+r*.72,cy+r*.3,r*.17)+kSmile(cx,cy+r*.3,r*.21,Math.max(1.3,r*.1));const kStarD=(cx,cy,R)=>{let d="";for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?R*.45:R;d+=(i?"L":"M")+(cx+Math.cos(a)*rr).toFixed(1)+" "+(cy+Math.sin(a)*rr).toFixed(1)+" "}return d+"Z"};const kWeld=(parts,stroke)=>parts.map(f=>f(stroke)).join("")+parts.map(f=>f('stroke="none"')).join("");const X={shell:"shell",gem:"gem",crab:"crab",fish:"fish",star:"star",key:"key",turtle:"turtle",banana:"banana",map:"map",sun:"sun",moon:"moon",boat:"sailboat",hat:"topHat",bee:"bee",monkey:"monkey",ball:"soccerBall",anchor:"anchor",swim:"swim",row:"row",whale:"whaleSpout",mouse:"mouse",tiger:"tiger",island:"island",egg:"egg",orange:"orange",box:"box",pencil:"pencil",q:"question",face:"face"};const COL={red:"#D9423A",blue:"#2F7FD9",green:"#3FA34D",yellow:"#F2C01E",purple:"#8E5BC9"};const svg=(w,h,body,alt,dw)=>`<svg viewBox="0 0 ${w} ${h}" width="${dw||w}" role="img" aria-label="${alt||"Picture"}">${body}</svg>`;const em=(x,y,e,s)=>F.picXY(x,y,e,s)||`<text x="${x}" y="${y}" font-size="${s}" text-anchor="middle" dominant-baseline="central">${e}</text>`;const frame=(w,h,fill)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${fill||"var(--surface)"}" stroke="var(--line)" stroke-width="4"/>`;function parrotIcon(x,y,s){const k=s/150;return`<g transform="translate(${x},${y}) scale(${k.toFixed(4)})"><image href="data:image/webp;base64," x="-66" y="-78" width="142" height="156"/></g>`}const actPic=(x,y,n,s)=>{const d=window.TP_ACT[n],h=s*1.2,w=Math.min(h*d[1]/d[2],s*1.45);const hh=w*d[2]/d[1];return`<image href="data:image/webp;base64,${d[0]}" x="${x-w/2}" y="${y-hh/2}" width="${w}" height="${hh}"/>`};const put=(x,y,e,s)=>typeof e==="string"&&e.slice(0,4)==="ACT:"?actPic(x,y,e.slice(4),s):e==="PARROT"?parrotIcon(x,y,s):em(x,y,e,s);const col=(...a)=>`<div class="figure" style="flex-direction:column;align-items:center;gap:14px">${a.join("")}</div>`;const tag=(x,y,t)=>`<circle cx="${x}" cy="${y}" r="20" fill="var(--sea-soft)" stroke="var(--line)" stroke-width="2"/><text x="${x}" y="${y+1}" font-size="22" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${t}</text>`;function cards(list,o){o=o||{};const c=o.cell||190,s=o.size||110,gap=16,extra=o.num?42:0,w=list.length*(c+gap)-gap+6,h=c+extra+6;let b="";list.forEach((e,i)=>{const x=3+i*(c+gap);b+=`<rect x="${x}" y="3" width="${c}" height="${c}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`+put(x+c/2,3+c/2,e,s);if(o.num)b+=`<text x="${x+c/2}" y="${c+34}" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">${i+1}</text>`});return svg(w,h,b,o.alt||"Picture cards")}function countRow(e,n,perRow,cell,size,alt){const rows=Math.ceil(n/perRow),w=perRow*cell+40,h=rows*cell+30;let b=frame(w,h);for(let i=0;i<n;i++)b+=put(20+i%perRow*cell+cell/2,15+Math.floor(i/perRow)*cell+cell/2,e,size);return svg(w,h,b,alt)}function coin(x,y,r){return`<circle cx="${x}" cy="${y}" r="${r}" fill="#FBD873" stroke="${INK}" stroke-width="${(r*.105).toFixed(1)}"/><circle cx="${x}" cy="${y}" r="${(r*.83).toFixed(1)}" fill="none" stroke="#C99A3A" stroke-width="${(r*.06).toFixed(1)}"/><path d="${kStarD(x,y-r*.31,r*.27)}" fill="#EFB53C"/>${kFace(x,y+r*.13,r*.62)}`}function coinRows(n,perRow,cell){const rows=Math.ceil(n/perRow),w=perRow*cell+40,h=rows*cell+30;let b=frame(w,h);for(let i=0;i<n;i++)b+=coin(20+i%perRow*cell+cell/2,15+Math.floor(i/perRow)*cell+cell/2,cell*.36);return svg(w,h,b,"Gold coins in rows")}function cmpPanel(t,eA,nA,cellA,eB,nB,cellB,alt){const w=880,h=214;let b=frame(w,h)+tag(42,42,t);for(let i=0;i<nA;i++)b+=put(90+i*cellA+cellA/2,62,eA,62);for(let i=0;i<nB;i++)b+=put(90+i*cellB+cellB/2,152,eB,62);return svg(w,h,b,alt)}function scatter(e,n,seed,alt){const W=410,H=300;let x=seed;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};const slots=[];for(let r=0;r<3;r++)for(let c=0;c<4;c++)slots.push([c,r]);for(let i=slots.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));const t=slots[i];slots[i]=slots[j];slots[j]=t}let b=frame(W,H);slots.slice(0,n).forEach(s=>{b+=put(Math.round(70+s[0]*90+(rnd()*20-10)),Math.round(60+s[1]*90+(rnd()*20-10)),e,50)});return svg(W,H,b,alt)}function palm(x,y,s){const L=["Q-70 -190 -112 -138","Q90 -190 132 -138","Q-40 -238 -108 -196","Q60 -242 128 -198","Q-30 -262 -66 -272","Q50 -266 92 -272"];const leaf=(d,c,w)=>`<path d="M10 -180 ${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;return`<g transform="translate(${x},${y}) scale(${s})"><path d="M0 0 Q-16 -90 10 -180" fill="none" stroke="${INK}" stroke-width="34" stroke-linecap="round"/><path d="M0 0 Q-16 -90 10 -180" fill="none" stroke="#C08A5E" stroke-width="24" stroke-linecap="round"/>`+L.map(d=>leaf(d,INK,28)).join("")+L.map(d=>leaf(d,"#7FC08A",19)).join("")+`</g>`}const sand=(w,h,top)=>`<path d="M5 ${top+12} Q${w/2} ${top-18} ${w-5} ${top+12} V${h-30} Q${w-5} ${h-5} ${w-30} ${h-5} H30 Q5 ${h-5} 5 ${h-30} Z" fill="#EDD7A6"/>`;function pipScene(){const w=900,h=600;return svg(w,h,`<image href="data:image/webp;base64," x="0" y="0" width="900" height="600"/>`,"A parrot on a rock, a gold key on the sand, a treasure box, a big rock and a tall palm tree on a small island")}function turtleScene(){return svg(760,722,`<image href="data:image/webp;base64," x="0" y="0" width="760" height="722"/>`,"A sea turtle on a beach at night next to a nest of eggs in the sand, with the moon and stars above",520)}const GEMS=[["c","red"],["s","blue"],["s","red"],["c","red"],["c","blue"],["s","red"],["s","blue"],["c","red"]];function gemsFig(){const cell=170,w=4*cell+40,h=2*150+30;let b=frame(w,h);GEMS.forEach((g,i)=>{const cx=20+i%4*cell+cell/2,cy=15+Math.floor(i/4)*150+75,f=COL[g[1]];if(g[0]==="c")b+=`<circle cx="${cx}" cy="${cy}" r="52" fill="${f}" stroke="${INK}" stroke-width="4.5"/><path d="M${cx-30} ${cy-14} q6 -20 26 -26" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" opacity=".7"/>`+kFace(cx,cy+4,34);else b+=`<rect x="${cx-50}" y="${cy-50}" width="100" height="100" rx="15" fill="${f}" stroke="${INK}" stroke-width="4.5"/><path d="M${cx-34} ${cy-12} v-22 h22" fill="none" stroke="#fff" stroke-width="6" stroke-linecap="round" opacity=".7"/>`+kFace(cx,cy+4,33)});return svg(w,h,b,"Eight gems: red and blue circles and squares, mixed up")}const PICKS=[[X.turtle,6],[X.crab,4]];function chartFig(){const cell=92,lab=130,cols=7,w=lab+cols*cell+8,h=PICKS.length*cell+8;let b="";PICKS.forEach((r,ri)=>{const y=4+ri*cell;b+=`<rect x="4" y="${y}" width="${lab}" height="${cell}" rx="10" fill="#D7EDF3" stroke="${INK}" stroke-width="3"/>`+em(4+lab/2,y+cell/2,r[0],66);for(let c=0;c<cols;c++){b+=`<rect x="${4+lab+c*cell}" y="${y}" width="${cell}" height="${cell}" rx="8" fill="#FBF6EF" stroke="${INK}" stroke-width="2"/>`;if(c<r[1])b+=TP_KIDPIC(4+lab+c*cell+cell/2,y+cell/2,70,0+ri*7+c)}});return svg(w,h,b,"Picture chart with a turtle row and a crab row. Each face is one pick.")}function shapesFig(){const st=`stroke="${INK}" stroke-width="5" stroke-linejoin="round"`;const b=`<circle cx="100" cy="125" r="82" fill="${COL.red}" ${st}/><polygon points="290,28 232,214 348,214" fill="${COL.yellow}" ${st}/><rect x="412" y="52" width="146" height="146" fill="${COL.blue}" ${st} stroke-linejoin="miter"/><rect x="618" y="80" width="204" height="92" fill="${COL.green}" ${st} stroke-linejoin="miter"/><polygon points="868,72 1012,72 918,196" fill="${COL.purple}" ${st}/>`;return svg(1030,240,b,"A red circle, a yellow triangle, a blue square, a green rectangle, and a purple triangle")}function placeScene(){return svg(1e3,500,`<image href="data:image/webp;base64," x="0" y="0" width="1000" height="500"/>`,"A beach with a palm tree with a monkey up in it, a ball in front of the tree, a table with a parrot on it and a crab under it, a turtle, and an open treasure chest with a gem in it")}function paper(shape){let b=`<image href="data:image/png;base64," x="1" y="8" width="168" height="202"/>`;if(shape==="tri")b+=`<polygon points="85,84 34,176 136,176" fill="none" stroke="${PUPIL}" stroke-width="6" stroke-linejoin="round"/>`;if(shape==="circle")b+=`<circle cx="85" cy="130" r="50" fill="none" stroke="${PUPIL}" stroke-width="6"/>`;return svg(170,220,b,shape==="write"?"A paper with a drawing on top and a line for writing below":"A shape drawn on paper")}function solidCards(){return`<div class="figure" style="align-items:center">${F.pic(X.orange,"","7.5rem")}${paper("tri")}${F.pic(X.box,"","7.5rem")}${paper("circle")}</div>`}const POLES=[["blue",210],["yellow",70],["green",270],["red",120],["purple",165]];function polesFig(){const w=900,h=350,base=318;let b=frame(w,h)+`<path d="M30 ${base} H870" stroke="${INK}" stroke-width="16" stroke-linecap="round"/><path d="M30 ${base} H870" stroke="#EDD7A6" stroke-width="10" stroke-linecap="round"/>`;POLES.forEach((p,i)=>{const x=110+i*170,top=base-p[1],f=COL[p[0]];b+=`<rect x="${x-10}" y="${top}" width="20" height="${p[1]}" rx="7" fill="${f}" stroke="${INK}" stroke-width="3.4"/><polygon points="${x+10},${top+3} ${x+86},${top+23} ${x+10},${top+43}" fill="${f}" stroke="${INK}" stroke-width="3.4" stroke-linejoin="round"/>`});return svg(w,h,b,"Five flag poles of different heights: blue, yellow, green, red, purple")}function patRow(t,list){const cell=100,w=(list.length+1)*cell+90,h=120;let b=frame(w,h)+tag(40,60,t);list.forEach((e,i)=>{b+=put(70+i*cell+cell/2,60,e,62)});const qx=70+list.length*cell;b+=`<rect x="${qx+8}" y="16" width="84" height="88" rx="14" fill="var(--sea-soft)" stroke="var(--sea)" stroke-width="4" stroke-dasharray="10 8"/><text x="${qx+50}" y="62" font-size="60" font-weight="800" text-anchor="middle" dominant-baseline="central" fill="var(--sea)">?</text>`;return svg(w,h,b,"A repeating pattern with a question mark at the end")}function chestFig(){const b=`<path d="M70 150 C70 44 350 44 350 150 Z" fill="#C08A5E" stroke="${INK}" stroke-width="5"/><path d="M86 142 C90 66 330 66 334 142" fill="none" stroke="#E0B072" stroke-width="9" stroke-linecap="round"/><rect x="70" y="150" width="280" height="118" rx="18" fill="#B07A52" stroke="${INK}" stroke-width="5"/><rect x="72" y="182" width="276" height="14" fill="#E0B072"/><rect x="108" y="152" width="16" height="114" fill="#E0B072"/><rect x="296" y="152" width="16" height="114" fill="#E0B072"/><rect x="190" y="136" width="40" height="52" rx="12" fill="#F7CC5A" stroke="${INK}" stroke-width="4"/><circle cx="210" cy="156" r="6" fill="${PUPIL}"/><rect x="207" y="158" width="6" height="16" rx="3" fill="${PUPIL}"/>`+kFace(210,228,46)+em(210,46,X.q,70)+em(52,60,X.q,44)+em(368,60,X.q,44);return svg(420,280,`<image href="data:image/webp;base64," x="55" y="15" width="311" height="250"/>`+em(52,60,X.q,44)+em(368,60,X.q,44),"A treasure chest with question marks")}function ratherFig(){const one=(e,alt)=>svg(300,260,frame(300,260)+em(150,130,e,170),alt);return`<div class="figure" style="align-items:center">${one(X.boat,"A sailboat")}<span class="big">or</span>${one(X.island,"An island with a palm tree")}</div>`}const PIP="Pip the parrot found a shiny gold key on the beach. She flew to the big rock, but the key did not open anything there. Next, she flew to the tall palm tree and saw a little wooden box. <strong>(Stop here. Ask what Pip will do next.)</strong> Pip put the key in the box and turned it. Click! The box opened, and inside were crunchy seeds for Pip and her friends.";const TURTLE="Sea turtles live in the ocean. They have flippers that help them swim. A mother sea turtle crawls onto the beach at night. She digs a hole in the sand and lays her eggs in it. Then she covers the eggs with sand and goes back to the sea. When the babies hatch, they crawl to the water.";const LETTERS=["O","S","A","M","T","B","X","E","R","K","s","o","m","a","t","e"];const NUMS=["3","1","5","2","7","4","10","6","8","9"];const PAT1=[X.shell,X.star,X.shell,X.star,X.shell,X.star,X.shell];const PAT2=[X.crab,X.crab,X.fish,X.fish,X.crab,X.crab,X.fish];const PAT3=[X.key,X.gem,X.banana,X.key,X.gem,X.banana,X.key];const FIND12=["D","h","P","q","G","w","N","y","U","j","F","l"];function findLetterFig(){const cell=152,per=6,w=per*cell+40,h=348;let b=frame(w,h);FIND12.forEach((L,i)=>{const cx=20+i%per*cell+cell/2,cy=26+Math.floor(i/per)*168;b+=`<rect x="${cx-56}" y="${cy}" width="112" height="128" rx="20" fill="#FBF1E4" stroke="${INK}" stroke-width="4"/>`;b+=window.TP_LETTER_CARD(L,cx,cy)});return svg(w,h,b,"Twelve cards laid out in two rows of six. Each card has one printed letter on it.")}const BENCH_SAMPLE="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself.";const BENCH_DECK="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of any deck. A child sitting exactly at that goal still lands near 60 percent of whatever sample you show, and the suggested rating reads that as approaching. Set the rating yourself against those two counts.";const BENCH_FULL="End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. The two inventories are scored under one code, so a child right at goal lands near 33 of 52 and the suggested rating reads that as approaching. Hold the uppercase count and the lowercase count against the two numbers above and set the rating yourself.";const ALPHA_FULL=E.alphabet({std:["TK.ELA.FLS.2.4"],sounds:false}).map(p=>Object.assign({},p,{key:p.key.concat([BENCH_FULL])}));const STOPS=[{id:1,title:"Letter Treasure",short:"Letters",parts:[{title:"Find the Letter",std:["TK.ELA.FLS.2.4"],n:10,dur:90,dir:"Listen to your teacher. Point to the letter on your screen.",desc:"matching a spoken letter name to its printed form (12 cards, 6 uppercase and 6 lowercase)",fig:()=>F.row(findLetterFig()),key:["Say: Here are twelve letter cards from the treasure chest. I will say a letter name. Point to the card with that letter.","Say: Point to the letter q. (top row, fourth card)","Say: Point to the letter N. (bottom row, first card)","Say: Point to the letter h. (top row, second card)","Say: Point to the letter F. (bottom row, fifth card)","Say: Point to the letter y. (bottom row, second card)","Say: Point to the letter D. (top row, first card)","Say: Point to the letter l. (bottom row, sixth card)","Say: Point to the letter G. (top row, fifth card)","Say: Point to the letter j. (bottom row, fourth card)","Say: Point to the letter P. (top row, third card)","The top row reads D, h, P, q, G, w and the bottom row reads N, y, U, j, F, l. Six cards are uppercase and six are lowercase, and two of the twelve are never asked for.","This is the direction the standard asks for: the child hears a name and finds the printed letter. Keep the uppercase and the lowercase results apart in your notes.","q, j and y all hang below the line, and lowercase l is a plain upright stroke. If the child points to the wrong one of those, write down which one.","End of TK goal for this standard: match about 15 to 20 of the 26 uppercase letters and about 12 to 16 of the 26 lowercase. Those are counts of letters, not a share of them. A child sitting right at that goal gets about 6 of these 10, which the suggested rating reads as approaching. Count the uppercase and the lowercase separately, hold each against the number above, and set the rating yourself."]},{title:"Name the Letter",std:["TK.ELA.FLS.2.4"],kind:"words",full:ALPHA_FULL,words:LETTERS,unit:"Letter",n:16,dur:75,dir:"Say the name of each letter.",desc:"naming uppercase and lowercase letters (10 uppercase, 6 lowercase)",key:["Say: These letters fell out of the treasure chest. Tell me the name of each letter. Click Next after each one.","Correct means the child says the letter name. If the child gives the sound, ask once: What is the name of this letter?","The first 10 are uppercase (O S A M T B X E R K). The last 6 are lowercase (s o m a t e). Write down the ones missed.","End of TK goal: about 15 to 20 uppercase and 12 to 16 lowercase letter names. This deck is a sample of 16, so write uppercase and lowercase results in your notes.","If the child misses 4 in a row, stop and change the number tried.","Find the Letter at the top of this stop is the part this standard is written for. The standard asks the child to match a spoken name to its printed form, and naming a letter on sight is harder than that, so rate this standard on the Find the Letter count and keep this deck as the extra note.",BENCH_DECK]}]},{id:2,title:"Count the Treasure",short:"Count",parts:[{std:["TK.MATH.1.2"],n:5,dur:120,dir:"First count some small things from near you. Then count the pictures on the screen.",desc:"counting 10 or more real objects one by one where the teacher can see, then counting groups of 6, 10, and 13 objects one by one on the screen",fig:()=>col(countRow(X.shell,6,6,96,64,"A row of shells"),countRow(X.gem,10,10,92,60,"A row of gems"),coinRows(13,5,92)),key:["Start with real things, before the screen. Say: Go and get ten small things you can hold, like spoons, blocks, socks or crayons, and set them on the table where I can see them. Then say: Move each one over to the side as you count it out loud. (One number word for each thing moved, no skips and no double counts. Moving each object is what makes the matching visible to you, so watch the hands as well as the numbers.)","Say: Push them back into a pile, add a few more, and count the whole lot again the same way. (Any number past ten. The goal is 10 or more with one number word for each object. If the count breaks down partway, write down the number it broke at.)","Those first two counts are the evidence for this standard, because they are the ones you can see for yourself. The screen rows below are still worth doing and they show whether a count holds together over bigger groups, but the child is pointing at a monitor you cannot see, so do not rate this standard on them alone and do not rate it on what an adult in the room reports.","Say: Point to each shell on your screen and count out loud. (6 shells) Look for one number word for each shell, with no skips and no double counts.","Say: Now count the gems. (10 gems)","Say: Now count the gold coins. (13 coins, in rows of 5, 5, and 3)","On the screen rows, have the child say the numbers slowly enough that you can hear one number word for each picture, and watch the child's eyes move along the row. Where you cannot tell, leave the row out of the count rather than taking an adult's word for it.","Count an item correct only when the last number said matches the number of objects. Note where the count broke down: skipped a number, counted one twice, or lost track after 10."]}]},{id:3,title:"Parrot Talk",short:"Sounds",parts:[{title:"First Sounds",std:["TK.ELA.FLS.2.1"],n:4,dur:45,dir:"Listen to your teacher. Say the first sound.",desc:"saying the first sound of a pictured word",fig:()=>F.row(cards([X.sun,X.moon,X.fish,X.boat],{cell:170,size:100,alt:"Sun, moon, fish, boat"})),key:["Model first: Map. The first sound in map is /m/. Now you try.","Point to the sun. Say: Sun. What is the first sound in sun? (/s/)","Point to the moon. Say: Moon. What is the first sound in moon? (/m/)","Point to the fish. Say: Fish. What is the first sound in fish? (/f/)","Point to the boat. Say: Boat. What is the first sound in boat? (/b/)","The answer is the sound, not the letter name. If the child says a letter name, ask: What sound do you hear first?"]},{title:"Rhyme Time",std:["TK.ELA.FLS.2.3"],n:3,dur:45,dir:"Listen to your teacher. Say a word that rhymes.",desc:"making a rhyme for a given word",fig:()=>F.row(cards([X.hat,X.shell,X.bee],{cell:170,size:100,alt:"Hat, shell, bee"})),key:["Model first: Log, dog, fog. They rhyme. They sound the same at the end.","Point to the hat. Say: Tell me a word that rhymes with hat. (cat, bat, mat, sat, zat)","Point to the shell. Say: Tell me a word that rhymes with shell. (bell, well, tell, yell, mell)","Point to the bee. Say: Tell me a word that rhymes with bee. (tree, sea, key, me, zee)","Real words and silly words both count. A rhyme that is close but not perfect counts too."]},{title:"Slow Parrot",std:["TK.ELA.FLS.2.2"],n:4,dur:45,dir:"Listen to the slow parrot talk. Say the whole word.",desc:"blending syllables and sounds into a word with picture support",fig:()=>F.row(cards([X.key,X.turtle,X.map,X.banana],{cell:170,size:100,alt:"Key, turtle, map, banana"})),key:["Say: Pip the parrot talks very slowly. Put the parts together and tell me the word. The pictures can help you. (The pictures are not in the same order as the words.)","Say with a pause between the parts: tur ... tle. (turtle)","Say: ba ... na ... na. (banana)","Say the two sounds: /k/ ... /ee/. (key)","Say the three sounds: /m/ ... /a/ ... /p/. (map)","The first two are syllables. The last two are single sounds. Note which kind the child can blend."]}]},{id:4,title:"Numbers Ahoy",short:"Numbers",parts:[{title:"Number Cards",std:["TK.MATH.1.5"],kind:"words",words:NUMS,unit:"Number",n:10,dur:45,dir:"Say the name of each number.",desc:"naming the numerals 1 to 10",key:["Say: What number is this? Click Next after each one.","Correct means the child says the number name. Write down the ones missed. Watch for 6 and 9 mixed up.","If the child counts up on fingers to find the name, note it. The goal is to know each numeral on sight."]},{title:"More or Fewer",std:["TK.MATH.1.6"],n:3,dur:50,dir:"Look at the pictures. Answer out loud.",desc:"comparing two groups by counting (more, same, fewer)",fig:()=>col(cmpPanel(1,X.crab,5,90,X.fish,3,90,"A row of crabs above a row of fish"),cmpPanel(2,X.shell,4,90,X.star,4,90,"A row of shells above a row of stars"),cmpPanel(3,"PARROT",6,124,X.banana,8,84,"A row of parrots above a row of bananas")),key:["Top box. Say: Are there more crabs or more fish? How do you know? (More crabs. 5 crabs and 3 fish.)","Middle box. Say: Are there more shells, more stars, or the same number of each? (The same. 4 shells and 4 stars.)","Bottom box. Say: Which group has fewer, the parrots or the bananas? (Fewer parrots. 6 parrots and 8 bananas.)","In the bottom box the parrots are spread out, so their row looks longer. Look for counting, not guessing from how long the row is.","Listen for the words more, same, fewer, or less."]}]},{id:5,title:"Pip and the Key",short:"Story",parts:[{std:["TK.ELA.R.3.2"],n:3,dur:90,read:PIP,dir:"Listen to the story. Then answer out loud.",desc:"questions about the character, the order of events, and what happens next in a story read aloud",fig:()=>F.row(pipScene()),key:["Read the story out loud. Stop after the third sentence, when Pip sees the little box.","Ask at the stopping place: What do you think Pip will do next? (Any guess that fits the story, like try the key in the box or open the box.) Then read the rest.","Ask: Who is this story about? What did Pip find on the beach? (Pip the parrot. A gold key.)","Ask: Where did Pip go first? Where did Pip go after that? What was inside the box? (First the big rock, then the palm tree. Seeds were in the box.)","If picture supports are on, the picture on the screen can help the child remember. Count the last question correct when the two places are in the right order."]}]},{id:6,title:"Sort and Chart",short:"Sort",parts:[{title:"Sort the Gems",std:["TK.MATH.2.5"],n:3,label:"checks met",dur:60,dir:"Look at the gems. Tell which ones go together.",desc:"sorting objects by color and by shape",fig:()=>F.row(gemsFig()),key:["Say: These gems got mixed up. Which ones go together? Tell me why. (Sorts by one thing and says what it is. By color: 5 red and 3 blue. By shape: 4 circles and 4 squares.)","Say: Now sort them a different way. (Uses the other way: color if shape came first, shape if color came first.)","Point your mouse at one blue square. Say: Tell me two things about this gem. (It is blue and it is a square.)","The child can name the groups out loud, like the red ones or the round ones. You do not need to move anything."]},{title:"Picture Chart",std:["TK.MATH.3.4"],n:4,dur:60,dir:"Look at the chart. Answer out loud. Then make marks on your paper.",desc:"reading, copying, and adding to a picture chart with two groups",fig:()=>F.row(chartFig()),key:["Say: Some children picked the beach animal they like best, the turtle or the crab. Each face is one child. How many children picked the turtle? (6)","Say: Did more children pick the turtle or the crab? (The turtle. 6 is more than 4.)","Say: On your paper, make one mark for each child who picked the crab. Hold it up. (4 marks, one for each face in the crab row)","Say: One more child picks the crab. What should we add to the chart? (One more face in the crab row, because each face is one child. That makes 5.)"]}]},{id:7,title:"Sea Turtle Facts",short:"Turtles",parts:[{std:["TK.ELA.R.3.3"],n:3,dur:80,read:TURTLE,dir:"Listen to your teacher read about sea turtles. Then answer out loud.",desc:"making an inference, making a connection, and asking a question about an informational text read aloud",fig:()=>F.row(turtleScene()),key:["Read the facts out loud. If picture supports are on, the child can look at the picture while listening.","Ask: Why do you think the mother turtle covers her eggs with sand? (A reason that makes sense: to hide them, to keep them safe, or to keep them warm. The text does not say why, so the child has to figure it out.)","Ask: What other animals do you know that lay eggs? (Uses what the child already knows: birds, chickens, ducks, frogs, fish, snakes, lizards.)","Say: What do you want to know about sea turtles? Ask me a question. You can start with What, Where, or How. (Asks a real question about sea turtles. Telling a fact is not asking a question.)"]}]},{id:8,title:"Shape Island",short:"Shapes",parts:[{title:"Name the Shapes",std:["TK.MATH.4.1"],n:6,dur:65,dir:"Look at the shapes. Answer out loud. Then draw one on your paper.",desc:"naming, describing, and drawing circles, squares, rectangles, and triangles",fig:()=>F.row(shapesFig()),key:["Say: What shape is the red one? (circle)","Say: What shape is the blue one? (square)","Say: What shape is the green one? (rectangle)","Say: Two of these shapes are triangles. Which colors are they? (yellow and purple)","Say: Tell me about the blue square. How many sides does it have? How many corners? (4 sides and 4 corners. Words like straight or pointy are a plus.)","Say: Draw a triangle on your paper. Hold it up. (A closed shape with 3 sides and 3 corners. It does not need to be neat.)"]},{title:"Where Is It?",std:["TK.MATH.4.5"],n:6,dur:55,dir:"Look at the picture. Answer out loud.",desc:"position words (on, under, in, between, in front of, up)",fig:()=>F.row(placeScene()),key:["Say: What is on the table? (the parrot)","Say: What is under the table? (the crab)","Say: What is in the treasure chest? (the gem)","Say: What is between the table and the treasure chest? (the turtle)","Say: Is the ball in front of the tree or behind the tree? (in front of)","Say: Where is the monkey? (Up in the tree, or on the tree. Look for a position word, not only pointing.)"]}]},{id:9,title:"Message in a Bottle",short:"Write",parts:[{title:"Sound Letters",std:["TK.ELA.W.4.2"],n:3,dur:60,dir:"Listen for the sound. Write the letter on your paper and hold it up.",desc:"writing the letter for a beginning sound (m, s, t)",fig:()=>F.row(cards([X.mouse,X.star,X.tiger],{cell:180,size:110,alt:"Mouse, star, tiger"})),key:["Point to the mouse. Say: Mouse starts with /m/. Write the letter that makes the /m/ sound. Hold it up. (m or M)","Point to the star. Say: Star starts with /s/. Write the letter for /s/. (s or S)","Point to the tiger. Say: Tiger starts with /t/. Write the letter for /t/. (t or T)","A letter counts when you can tell what it is. Backward or wobbly letters still count. Uppercase or lowercase is fine.","You give the sound. The child picks and writes the letter. If an adult names the letter for the child, do not count that one."]},{title:"Label Your Treasure",std:["TK.ELA.W.4.4"],n:3,label:"checks met",dur:90,dir:"Draw a treasure on your paper. Write letters to tell what it is. Hold it up.",desc:"writing letters to label a drawing",fig:()=>`<div class="figure" style="align-items:center">${F.pic(X.pencil,"","6rem")}${paper("write")}${F.pic(X.gem,"","6rem")}</div>`,key:["Say: Draw your own treasure on your paper. Then write a word or some letters to tell what it is. Hold it up and tell me what you wrote.","Look for: writing that is separate from the drawing (letters or marks that look like letters, not only a picture).","Look for: 2 or more letters you can recognize. They do not need to spell the word.","Look for: the child tells you what the writing says, like It says gold. This shows the letters stand for a word or an idea.","If the child writes only a name, that is a fine start. Ask: What does it say? Then ask for some letters about the treasure too."]}]},{id:10,title:"Flags and Patterns",short:"Line Up",parts:[{title:"Flag Line Up",std:["TK.MATH.3.2"],n:3,dur:45,dir:"Look at the flag poles. Say them in order from shortest to tallest.",desc:"ordering 5 objects by height",fig:()=>`<div class="figure"><img alt="Five flag poles of different heights: blue, yellow, green, red, purple" style="max-width:100%;width:760px;height:auto" src="data:image/webp;base64,"></div>`,key:["Say: Which flag pole is the tallest? (green)","Say: Which flag pole is the shortest? (yellow)","Say: Put the flag poles in order from shortest to tallest. Tell me the colors in order. (yellow, red, purple, blue, green)","The last one is the main check: all 5 in order. If only part of the order is right, write the order the child said in your notes."]},{title:"What Comes Next?",std:["TK.MATH.2.6"],n:4,dur:60,dir:"Look at each row. Say what comes next.",desc:"extending repeating patterns and naming the part that repeats",fig:()=>col(patRow(1,PAT1),patRow(2,PAT2),patRow(3,PAT3)),key:["Top row. Say: Shell, star, shell, star, shell, star, shell. What comes next? (star)","Middle row. Say: Look at this pattern. What comes next? (fish. The pattern is crab, crab, fish, fish.)","Bottom row. Say: What comes next here? (the gem, and diamond is fine too. The pattern is key, gem, banana.)","Go back to the top row. Say: What part keeps repeating over and over? (shell, star)","Extra if there is time: clap and pat the top pattern together (clap, pat, clap, pat). This shows the child can copy a pattern in a new way."]}]},{id:11,title:"Captain’s Chat",short:"Chat",parts:[{title:"Name It",std:["TK.ELA.L.1.1"],n:6,dur:55,dir:"Look at each picture. Answer out loud.",desc:"naming objects, actions, and describing words from pictures",fig:()=>F.row(cards([X.boat,X.crab,X.anchor,"ACT:read",X.row,X.whale],{cell:150,size:92,num:true,alt:"Boat, crab, anchor, a person reading, a person rowing, a whale"})),key:["Picture 1. Say: What is this? (boat, sailboat, or ship)","Picture 2. Say: What is this? (crab)","Picture 3. Say: What is this? (anchor. This is a harder word.)","Picture 4. Say: What is this person doing? (reading, or looking at a book)","Picture 5. Say: What is this person doing? (rowing or paddling a boat)","Picture 6. Say: This is a whale. Tell me two words about what a whale is like. (Describing words such as big, huge, blue, wet, smooth, heavy.)","Pictures 1 to 3 are naming words, 4 and 5 are action words, and 6 is describing words. Note which kind was hard."]},{title:"Mystery Chest",std:["TK.ELA.LS.1.5"],n:3,label:"checks met",dur:55,dir:"Something is hiding in the chest. Ask your teacher questions to find out what it is.",desc:"asking questions and follow-up questions to find out information",fig:()=>F.row(chestFig()),key:["Your secret: a banana is hiding in the chest. Do not tell.","Say: Something is hiding in my treasure chest. Ask me questions to find out what it is. You can ask things like: Is it an animal? What color is it?","Answer each question in a few words: It is yellow. You can eat it. It is a fruit. You peel it. It is long and curved.","Look for: asks a real question to get information (not only a guess, like A ball!).","Look for: asks a follow-up question that builds on your answer (after You can eat it, asks Is it a fruit? or Is it sweet?).","Look for: checks the idea with a question at the end (Is it a banana?). If the child is stuck after 4 or 5 questions, give one more clue."]},{title:"Would You Rather",std:["TK.ELA.LS.1.7"],n:3,label:"checks met",dur:50,dir:"Pick one. Tell your teacher why.",desc:"sharing an opinion with a reason and details",fig:()=>ratherFig(),key:["Say: Would you rather sail on the boat or play on the island? Tell me which one and why.","Look for: tells an opinion (picks one).","Look for: gives a reason that explains the pick. If there is no reason, ask once: Why?","Say: Tell me more. What would you do there? What would you see? Look for: 2 or more details in the description."]}]}];const LEVELUPS={1:{id:"L1",lv:true,title:"Level Up: Letter Names",std:["RF.K.1"],needs:["TK.ELA.FLS.2.4"],n:5,dir:"Say the name of each letter.",html:()=>F.cards(["Q","V","Z","r","q"],{size:"5rem",min:130}),key:["Q (the name is cue)","V","Z (zee)","r, the lowercase letter. Watch for r and n mixed up.","q, the lowercase letter. Watch for q mixed up with p or g.","TK asks for many letter names. Kindergarten asks for all 52 uppercase and lowercase letter names, so these are 5 that TK children miss most often. The name is the answer here, not the sound."]},2:{id:"L2",lv:true,title:"Level Up: How Many?",std:["K.CC.B.4"],needs:["TK.MATH.1.2"],n:3,dir:"Count the gold coins. Then answer out loud.",html:()=>col(coinRows(16,8,88),coinRows(16,4,88)),key:["Point to the top group. Say: Count the gold coins. How many are there? (16. Look for the child to say 16 as the answer to how many, without counting again. The last number said tells how many.)","Point to the bottom group. Say: I moved the same coins into this group. I did not add any or take any away. How many coins are in this group? (16. The Kindergarten idea is that the number stays the same when the coins are moved around. Saying 16 without counting again shows it best.)","Say: If one more coin drops in, how many will there be? (17. One more is the next number.)"]},4:{id:"L4",lv:true,title:"Level Up: Which Has More?",std:["K.CC.C.6"],needs:["TK.MATH.1.6"],n:3,dir:"Look at the pictures. Answer out loud.",html:()=>F.row(scatter(X.gem,9,11,"A group of gems"),scatter(X.key,7,23,"A group of keys"))+F.row(scatter(X.shell,8,5,"A group of shells"),scatter(X.star,8,37,"A group of stars")),key:["Ask: Look at the top boxes. Which has more, the gems or the keys? How do you know? (The gems. 9 is more than 7. Counts or matches to find out.)","Ask: So are there fewer keys or fewer gems? (Fewer keys. 7 is less than 9.)","Ask: Look at the bottom boxes. Are there more shells, more stars, or are they equal? (Equal. 8 shells and 8 stars.)"]},8:{id:"L8",lv:true,title:"Level Up: Flat or Solid",std:["K.G.A.3"],needs:["TK.MATH.4.1"],n:4,dir:"Look at each picture. Say flat or solid.",html:()=>solidCards(),key:["Say first: A flat shape is like a drawing on paper. A solid shape is thick, and you can hold it. Then ask: Is the orange flat or solid? (solid)","Ask: Is the triangle drawn on the paper flat or solid? (flat)","Ask: Is the box flat or solid? (solid)","Ask: Is the circle drawn on the paper flat or solid? (flat)"]}};let npOn={},tfOn={};function npHtml(){let h=`<div class="nl">`;for(let i=1;i<=10;i++)h+=`<button data-n="${i}" class="${npOn[i]?"on":""}" style="font-size:1.6rem">${i}</button>`;return h+`</div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){let c=`<div class="tf-wrap"><div class="tf">`;for(let k=0;k<10;k++)c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`;return c+`</div></div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear. The top row is a five frame.</p>`}function abcHtml(){return`<div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center">${"ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").map(c=>`<span style="border:2px solid var(--line);border-radius:10px;padding:2px 10px;font-family:var(--font-display);font-weight:800;font-size:1.7rem">${c}${c.toLowerCase()}</span>`).join("")}</div>`}const TOOLS={np:{name:"Number path 1 to 10",std:["TK.MATH.1.2","TK.MATH.1.6","K.CC.C.6"],html:npHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{npOn[x.dataset.n]=!npOn[x.dataset.n];r()})},tf:{name:"Ten frame",std:["TK.MATH.1.2","TK.MATH.1.6","TK.MATH.3.4","K.CC.C.6"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},abc:{name:"Alphabet strip",std:["TK.ELA.W.4.2","TK.ELA.W.4.4"],html:abcHtml},talk:{name:"Talking starters",std:["TK.ELA.LS.1.7"],html:()=>`<ul class="starters"><li>I pick the ____ because ____.</li><li>There I would ____.</li><li>I would see ____.</li></ul><p class="small">Say a starter out loud for the child to finish.</p>`}};const SUP_CAVEATS=[{t:"np",std:["TK.MATH.1.5"],msg:"The number path shows the numerals in order. If it was open during Number Cards, the child may have counted along the path to find a name. That is not the same as knowing the numeral on sight."},{t:"np",std:["TK.MATH.1.2"],msg:"The number path helps the child keep the counting order. Note that the count was done with a visual."},{t:"tf",std:["TK.MATH.1.6","K.CC.C.6"],msg:"If you matched the two groups on the ten frame, the child compared with a model you built. Note that the comparing was supported."},{t:"abc",std:["TK.ELA.W.4.2","TK.ELA.W.4.4"],msg:"With the alphabet strip the child can find a letter and copy it. That still fits the standard, but note whether the child picked the right letter for the sound without help."},{t:"talk",std:["TK.ELA.LS.1.7"],msg:"The talking starter supplies the word because. Count the reason check as supported."},{t:"scribe",std:["TK.ELA.W.4.2","TK.ELA.W.4.4"],msg:"If an adult wrote the letters or guided the child’s hand, those letters do not count as the child’s writing."},{t:"adult",msg:"If the adult at home gave a hint or the answer, do not count that item as correct on the child’s own."},{t:"objects",std:["TK.MATH.1.2"],msg:"Counting real objects at home is a fine way to show this standard. Note what the child counted and how many."}];function stopLogs(st){const math=st.std.some(c=>/^TK\.MATH|^K\./.test(c)),write=st.std.some(c=>/\.W\.4\./.test(c)),out=["repeat","adult"];if(math)out.push("objects");out.push("time");if(write)out.push("scribe");out.push("brk");return out}return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:[],stopLogs,logNames:{adult:"Adult at home helped"}}}});
